'use client';

import { useState } from 'react'
import NewPMTilesMap from '@/components/map/NewPMTilesMap'

export default function Home() {
  const [mapError, setMapError] = useState<string | null>(null)

  if (mapError) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center">
        <div className="text-center">
          <div className="text-red-400 text-sm mb-3">
            Map Error: {mapError}
          </div>
          <button
            onClick={() => window.location.reload()}
            className="px-3 py-1 bg-white text-black text-sm rounded hover:bg-gray-100 transition-colors"
          >
            Retry
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-black text-white flex flex-col">
      {/* Top Header */}
      <div className="bg-black/90 backdrop-blur-sm border-b border-white/10 px-6 py-4 z-50">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-lg font-semibold">PMTiles Map Test</h1>
            <p className="text-sm text-gray-400">Testing PMTiles integration</p>
          </div>
        </div>
      </div>

      {/* Map Container */}
      <div className="flex-1">
        <NewPMTilesMap 
          className="w-full h-full"
          onMapLoad={(map) => {
            console.log('Map loaded successfully:', map);
          }}
          onMapError={(error) => {
            console.error('Map error:', error);
            setMapError(error.message);
          }}
        />
      </div>
    </div>
  )
} 